mapper.update:
UPDATE users
SET face_vector_id = #{faceVectorId}, login_type = 'FACE', updated_at = NOW()
WHERE user_id = #{userId}

mapper.select:
SELECT face_vector <=> #{queryVector, typeHandler=com.revy.talkblogback.handler.PgVectorTypeHandler}
FROM face_vectors
WHERE user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE users
SET last_login_time = NOW(), updated_at = NOW()
WHERE user_id = #{userId}

mapper.select:
SELECT u.user_id, u.username, u.email, u.phone, u.avatar_url, u.status, u.login_type, u.last_login_time, COALESCE(string_agg(r.role_name, ',' ORDER BY r.role_id), '') AS role_names FROM users u LEFT JOIN user_roles ur ON u.user_id = ur.user_id LEFT JOIN roles r ON ur.role_id = r.role_id
(lower(u.username) LIKE lower(concat('%', #{keyword}, '%')) OR lower(u.email) LIKE lower(concat('%', #{keyword}, '%')) OR lower(u.phone) LIKE lower(concat('%', #{keyword}, '%')))
GROUP BY u.user_id, u.username, u.email, u.phone, u.avatar_url, u.status, u.login_type, u.last_login_time, u.created_at ORDER BY u.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE users
SET status = #{status}, updated_at = NOW()
WHERE user_id = #{userId}
